class Solution {
public:
    vector<int> sortJumbled(vector<int>& mapping, vector<int>& nums) {
        auto getMapped = [&](int x) {
            if (x == 0) return mapping[0];
            int res = 0, place = 1;
            while (x > 0) {
                res += mapping[x % 10] * place;
                place *= 10;
                x /= 10;
            }
            return res;
        };
        int n = nums.size();
        vector<tuple<int, int, int>> items(n);
        for (int i = 0; i < n; i++) {
            items[i] = {getMapped(nums[i]), i, nums[i]};
        }
        sort(items.begin(), items.end());
        vector<int> res(n);
        for (int i = 0; i < n; i++) res[i] = get<2>(items[i]);
        return res;
    }
};

class Solution {
    public int[] sortJumbled(int[] mapping, int[] nums) {
        int n = nums.length;
        Integer[] idx = new Integer[n];
        int[] mapped = new int[n];
        for (int i = 0; i < n; i++) {
            idx[i] = i;
            mapped[i] = getMapped(nums[i], mapping);
        }
        Arrays.sort(idx, (a, b) -> {
            if (mapped[a] != mapped[b]) return Integer.compare(mapped[a], mapped[b]);
            return Integer.compare(a, b);
        });
        int[] res = new int[n];
        for (int i = 0; i < n; i++) res[i] = nums[idx[i]];
        return res;
    }
    private int getMapped(int x, int[] mapping) {
        if (x == 0) return mapping[0];
        int res = 0, place = 1;
        while (x > 0) {
            res += mapping[x % 10] * place;
            place *= 10;
            x /= 10;
        }
        return res;
    }
}

var sortJumbled = function(mapping, nums) {
    const getMapped = (x) => {
        if (x === 0) return mapping[0];
        let res = 0, place = 1;
        while (x > 0) {
            res += mapping[x % 10] * place;
            place *= 10;
            x = Math.floor(x / 10);
        }
        return res;
    };
    const items = nums.map((val, idx) => ({ val, idx, mapped: getMapped(val) }));
    items.sort((a, b) => {
        if (a.mapped !== b.mapped) return a.mapped - b.mapped;
        return a.idx - b.idx;
    });
    return items.map(it => it.val);
};
